SELECT

FROM TODAY_HISTORY_PAGE
WHERE
LOGIC_DEL = 0

    AND MONTH_VALUE = #{dto.monthValue}


    AND DAY_VALUE = #{dto.dayValue}


    AND HISTORY_KEY = #{dto.historyKey}


    AND PAGE_TITLE = #{dto.pageTitle}


    AND PAGE_URL = #{dto.pageUrl}


    AND CONTENT_HASH = #{dto.contentHash}


    AND LAST_SYNC_TIME = #{dto.lastSyncTime}


    AND ITEM_COUNT = #{dto.itemCount}


    AND RAW_HTML = #{dto.rawHtml}

ORDER BY create_time DESC

SELECT

FROM TODAY_HISTORY_PAGE
WHERE LOGIC_DEL = 0

    AND ID = #{dto.id}}


    AND MONTH_VALUE = #{dto.monthValue}


    AND DAY_VALUE = #{dto.dayValue}


    AND HISTORY_KEY = #{dto.historyKey}


    AND PAGE_TITLE = #{dto.pageTitle}


    AND PAGE_URL = #{dto.pageUrl}


    AND CONTENT_HASH = #{dto.contentHash}


    AND LAST_SYNC_TIME = #{dto.lastSyncTime}


    AND ITEM_COUNT = #{dto.itemCount}


    AND RAW_HTML = #{dto.rawHtml}

ORDER BY MODIFY_TIME DESC

SELECT

FROM TODAY_HISTORY_PAGE
WHERE LOGIC_DEL = 0

    AND ID = #{dto.id}}


    AND MONTH_VALUE = #{dto.monthValue}


    AND DAY_VALUE = #{dto.dayValue}


    AND HISTORY_KEY = #{dto.historyKey}


    AND PAGE_TITLE = #{dto.pageTitle}


    AND PAGE_URL = #{dto.pageUrl}


    AND CONTENT_HASH = #{dto.contentHash}


